:root {
  --bg: #1a1c2c;
  --card: #2a2d45;
  --accent: #f4a261;
  --accent-dark: #e76f51;
  --text: #f0e9d2;
  --button: #3b3f5c;
  --button-hover: #4f5478;
  --button-active: #f4a261;
  --door: #14162b;
  --display-bg: #0f111f;
  --focus: #f4a261;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
}

.card {
  background: var(--card);
  border-radius: 12px;
  padding: 1.5rem;
  box-shadow: 0 8px 0 #0d0f1a, 0 12px 24px rgba(0,0,0,0.5);
  width: 100%;
  max-width: 400px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1.5rem;
}

h1 {
  color: var(--text);
  font-size: 1.5rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  text-shadow: 2px 2px 0 var(--bg);
}

.panel {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1.25rem;
  width: 100%;
}

.display {
  background: var(--display-bg);
  border: 3px solid #0d0f1a;
  border-radius: 6px;
  padding: 0.75rem 1.5rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  min-height: 70px;
  box-shadow: inset 0 0 0 2px #2a2d45;
}

.floor-display {
  font-size: 2.5rem;
  font-weight: bold;
  color: var(--accent);
  font-family: 'Courier New', monospace;
  text-shadow: 0 0 8px var(--accent);
}

.direction-display {
  font-size: 2rem;
  color: var(--accent);
  transition: transform 0.2s;
  width: 2rem;
  text-align: center;
}

.direction-display.up {
  transform: rotate(0deg);
}

.direction-display.down {
  transform: rotate(180deg);
}

.direction-display.idle {
  opacity: 0.3;
}

.doors {
  display: flex;
  width: 100%;
  height: 80px;
  background: var(--door);
  border: 3px solid #0d0f1a;
  border-radius: 4px;
  overflow: hidden;
  position: relative;
}

.door {
  width: 50%;
  height: 100%;
  background: #2a2d45;
  border: 2px solid #0d0f1a;
  transition: transform 0.3s ease-in-out;
}

.door.left {
  transform: translateX(0);
}

.door.right {
  transform: translateX(0);
}

.doors.open .door.left {
  transform: translateX(-100%);
}

.doors.open .door.right {
  transform: translateX(100%);
}

.buttons {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0.75rem;
  width: 100%;
}

.floor-btn {
  background: var(--button);
  color: var(--text);
  border: none;
  border-radius: 6px;
  padding: 0.75rem 0;
  font-size: 1.25rem;
  font-weight: bold;
  font-family: 'Courier New', monospace;
  cursor: pointer;
  box-shadow: 0 4px 0 #1a1c2c;
  transition: background 0.15s, box-shadow 0.15s, transform 0.1s;
  position: relative;
}

.floor-btn:hover {
  background: var(--button-hover);
}

.floor-btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.floor-btn:active {
  transform: translateY(2px);
  box-shadow: 0 2px 0 #1a1c2c;
}

.floor-btn.queued {
  background: var(--accent);
  color: var(--bg);
  box-shadow: 0 4px 0 var(--accent-dark);
}

.floor-btn.queued:hover {
  background: var(--accent-dark);
}

.floor-btn.queued:active {
  box-shadow: 0 2px 0 var(--accent-dark);
}

[hidden] {
  display: none !important;
}

@media (max-width: 400px) {
  .card {
    padding: 1rem;
  }
  .floor-display {
    font-size: 2rem;
  }
  .floor-btn {
    font-size: 1.1rem;
    padding: 0.6rem 0;
  }
}

const currentFloorEl = document.getElementById('current-floor');
const directionEl = document.getElementById('direction');
const doorsEl = document.getElementById('doors');
const floorButtons = document.querySelectorAll('.floor-btn');

const MIN_FLOOR = 1;
const MAX_FLOOR = 6;
const MOVE_DELAY = 1000;
const DOOR_OPEN_DELAY = 800;

let currentFloor = 1;
let direction = 0; // -1 down, 0 idle, 1 up
let queue = [];
let moving = false;
let doorTimeout = null;
let moveTimeout = null;

function updateDisplay() {
  currentFloorEl.textContent = currentFloor;
  directionEl.textContent = direction === 1 ? '\u25b2' : direction === -1 ? '\u25bc' : '\u25cf';
  directionEl.className = 'direction-display ' + (direction === 1 ? 'up' : direction === -1 ? 'down' : 'idle');
}

function updateButtons() {
  floorButtons.forEach(btn => {
    const floor = parseInt(btn.dataset.floor, 10);
    btn.classList.toggle('queued', queue.includes(floor));
  });
}

function openDoors() {
  doorsEl.classList.add('open');
  clearTimeout(doorTimeout);
  doorTimeout = setTimeout(() => {
    doorsEl.classList.remove('open');
  }, DOOR_OPEN_DELAY);
}

function getNextFloor() {
  if (queue.length === 0) return null;
  // Pick the closest floor in the current direction, or any if idle
  if (direction === 1) {
    const above = queue.filter(f => f > currentFloor).sort((a, b) => a - b);
    if (above.length) return above[0];
  } else if (direction === -1) {
    const below = queue.filter(f => f < currentFloor).sort((a, b) => b - a);
    if (below.length) return below[0];
  }
  // If no floor in current direction or idle, pick the closest
  return queue.reduce((closest, f) => {
    return Math.abs(f - currentFloor) < Math.abs(closest - currentFloor) ? f : closest;
  }, queue[0]);
}

function moveStep() {
  if (queue.length === 0) {
    moving = false;
    direction = 0;
    updateDisplay();
    return;
  }

  const target = getNextFloor();
  if (target === null) {
    moving = false;
    direction = 0;
    updateDisplay();
    return;
  }

  if (target === currentFloor) {
    // Arrived at target
    queue = queue.filter(f => f !== currentFloor);
    updateButtons();
    openDoors();
    // Continue after doors close
    setTimeout(() => {
      if (queue.length > 0) {
        moveStep();
      } else {
        moving = false;
        direction = 0;
        updateDisplay();
      }
    }, DOOR_OPEN_DELAY);
    return;
  }

  // Determine direction
  direction = target > currentFloor ? 1 : -1;
  updateDisplay();

  // Move one floor after a delay (movement takes one second)
  moveTimeout = setTimeout(() => {
    currentFloor += direction;
    updateDisplay();

    // Check arrival at target
    if (currentFloor === target) {
      queue = queue.filter(f => f !== currentFloor);
      updateButtons();
      openDoors();
      setTimeout(() => {
        if (queue.length > 0) {
          moveStep();
        } else {
          moving = false;
          direction = 0;
          updateDisplay();
        }
      }, DOOR_OPEN_DELAY);
    } else {
      moveStep();
    }
  }, MOVE_DELAY);
}

function addToQueue(floor) {
  if (floor < MIN_FLOOR || floor > MAX_FLOOR) return;
  if (queue.includes(floor)) return;
  if (floor === currentFloor && !moving) {
    // Already here, just open doors
    openDoors();
    return;
  }
  queue.push(floor);
  updateButtons();
  if (!moving) {
    moving = true;
    moveStep();
  }
}

floorButtons.forEach(btn => {
  btn.addEventListener('click', () => {
    const floor = parseInt(btn.dataset.floor, 10);
    addToQueue(floor);
  });
});

// Initialize
updateDisplay();
updateButtons();
